//! Application hosting, separate from low-level JavaScript execution.
#[cfg(feature = "client")]
pub mod client;

/// Assets/configuration are generated by tokamak-build in the calling app.
#[cfg(feature = "client")]
#[macro_export]
macro_rules! context {
    () => {
        include!(concat!(env!("OUT_DIR"), "/tokamak_context.rs"))
    };
}

#[cfg(feature = "server")]
pub mod server {
    pub use ::server::{Backend, BackendConfig, Error, data::Storage};
    pub use engine::{Bundle, Limits, PoolConfig};
}
